const items = $input.all().map(i => i.json);
const headers = [
  "id",
  "url",
  "engine",
  "violations_count",
  "high_impact_count",
  "summary",
  "plan_json",
  "report_link",
  "run_id",
  "created_at"
];

function escapeCsv(value) {
  if (value == null) return "";
  let str = String(value);
  if (str.includes('"') || str.includes(',') || str.includes('\n')) {
    str = '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

const headerRow = headers.join(",");
const rows = items.map(item => headers.map(h => escapeCsv(item[h])).join(","));
const csvString = [headerRow, ...rows].join("\n");

return [{
  binary: {
    reports: {
      data: Buffer.from(csvString).toString('base64'),
      mimeType: 'text/csv',
      fileName: 'reports.csv'
    }
  }
}];

const items = $input.all().map(i => i.json);

const headers = [
  "id",
  "url",
  "engine",
  "violations_count",
  "high_impact_count",
  "summary",
  "plan_json",
  "report_link",
  "run_id",
  "created_at"
];

const headerRow = headers.join(",");

const rows = items.map(item => {
  return headers.map(h => {
    let val = item[h] ?? "";
    if (typeof val === "object") {
      val = JSON.stringify(val);
    }
    return `"${String(val).replace(/"/g, '""').replace(/\n/g, " ")}"`;
  }).join(",");
});

const data = headerRow + "\n" + rows.join("\n");

return [{ json: { data } }];

const cloudName = $env.STORAGE_ACCOUNT || $env.CLOUDINARY_CLOUD_NAME || "";
const fileName = $binary?.report?.fileName || null;
const scannedUrl = $json.scan_raw?.url || $json.context?.url || $json.url || "";

let report_link = null;

if (!($json?.error) && cloudName && fileName) {
  const fileNameWithoutExt = fileName.replace('.html', '');
  report_link = `${$env.STORAGE_PUBLIC_BASE}/${cloudName}${$env.STORAGE_UPLOAD_PATH || "/raw/upload"}/reports/html/${fileNameWithoutExt}.html`;
}

return [
  {
    json: {
      ...$json,
      url: scannedUrl,
      report_link,
    },
  },
];

const resp = $input.first().json;

// OpenAI and Azure return choices[0].message.content.
// Anthropic returns content[0].text. Accept either so the provider switch is
// a settings change rather than a code change.
const rawText =
  resp.choices?.[0]?.message?.content ??
  (Array.isArray(resp.content) ? resp.content.map(b => b?.text || "").join("") : "") ??
  "";

let content = {};
try {
  content = JSON.parse(rawText || "{}");
} catch (e) {
  content = { parse_error: e.message, raw: rawText || "" };
}

const usage = resp.usage || {};
// Anthropic names these input_tokens and output_tokens.
const promptTokens = usage.prompt_tokens ?? usage.input_tokens ?? 0;
const completionTokens = usage.completion_tokens ?? usage.output_tokens ?? 0;
const totalTokens = usage.total_tokens || (promptTokens + completionTokens);

const promptRatePerM = parseFloat($env.OPENAI_PROMPT_COST_PER_M || "0");
const completionRatePerM = parseFloat($env.OPENAI_COMPLETION_COST_PER_M || "0");

const promptCost = (promptTokens / 1_000_000) * promptRatePerM;
const completionCost = (completionTokens / 1_000_000) * completionRatePerM;
const totalCost = promptCost + completionCost;

return [{
  json: {
    message: { content },
    model: resp.model || $env.OPENAI_MODEL || "unknown",
    prompt_tokens: promptTokens,
    completion_tokens: completionTokens,
    total_tokens: totalTokens,
    ai_cost_usd: Number(totalCost.toFixed(6))
  }
}];

const raw = JSON.parse($json.stdout || "{}");

return [
  {
    json: {
      scan_raw: {
        violations: raw.violations || [],
        testEngine: raw.testEngine || { name: "axe-core" },
        timestamp: raw.timestamp || new Date().toISOString(),
        url: raw.url || "N/A",
      },
    },
  },
];

const raw = JSON.parse($json.stdout || "{}");

const violations = (raw.issues || []).map((issue) => ({
  id: issue.code || "unknown",
  impact: issue.type,
  help: issue.message,
  helpUrl: "",
  nodes: [{ target: [issue.selector || ""] }],
}));

// run-pa11y.js reports which engines actually produced this result in
// runnersUsed. Hardcoding "htmlcs" here mislabeled the report whenever
// PA11Y_RUNNER selected axe, or both, which is the shipped default.
const runnersUsed = Array.isArray(raw.runnersUsed) && raw.runnersUsed.length
  ? raw.runnersUsed.join(",")
  : "htmlcs";

return [
  {
    json: {
      scan_raw: {
        violations,
        testEngine: { name: "pa11y", version: runnersUsed },
        timestamp: new Date().toISOString(),
        url: raw.pageUrl || raw.documentTitle || "N/A",
      },
    },
  },
];

// --- retired criteria --------------------------------------------------------
// W3C removed 4.1.1 Parsing in WCAG 2.2 and advises treating it as always
// satisfied for HTML and XML content. HTML CodeSniffer still emits F77 for it.
// On one live scan this inflated 31 real failures to 99.
// https://www.w3.org/WAI/standards-guidelines/wcag/faq
const OBSOLETE_SC = ["4.1.1"];

function scFromRuleId(id) {
  const s = String(id || "");
  let m = s.match(/Guideline\d_\d\.(\d)_(\d)_(\d+)/);
  if (m) return m[1] + "." + m[2] + "." + m[3];
  m = s.match(/\b(\d)\.(\d)\.(\d+)\b/);
  if (m) return m[1] + "." + m[2] + "." + m[3];
  return null;
}

function isObsoleteFinding(v) {
  if (v && v.isObsolete === true) return true;
  const sc = (v && v.wcag_sc) || scFromRuleId(v && (v.id || v.code || v.rule));
  return !!sc && OBSOLETE_SC.indexOf(sc) !== -1;
}

return items.map((i) => {
  const raw = i.json.scan_raw || {};
  const engine = (raw.testEngine?.name || $env.SCAN_ENGINE || "unknown")
    .toString()
    .toLowerCase();
  const v = Array.isArray(raw.violations) ? raw.violations : [];

  const norm = (s) => {
    const x = String(s || "").toLowerCase();
    if (["critical", "serious", "error", "high"].includes(x)) return "high";
    if (["moderate", "warning", "medium", "med"].includes(x)) return "medium";
    if (["minor", "notice", "low"].includes(x)) return "low";
    return "-";
  };

  const vNorm = v.map((x) => ({
    id: x.id || x.rule || x.issueId || "-",
    impact: norm(x.impact || x.type),
    help: x.help || x.description || x.message || "-",
    nodes: Array.isArray(x.nodes) ? x.nodes : [],
    helpUrl: x.helpUrl || x.url || "",
    tags: Array.isArray(x.tags) ? x.tags : [],
  }));

  const vCountable = vNorm.filter((y) => !isObsoleteFinding(y));

  const counts = {
    total: vCountable.length,
    high: vCountable.filter((y) => y.impact === "high").length,
    medium: vCountable.filter((y) => y.impact === "medium").length,
    low: vCountable.filter((y) => y.impact === "low").length,
    obsolete: vNorm.length - vCountable.length,
  };

  const prioritized = vCountable.map((r) => ({
    issueId: r.id,
    wcag: r.tags
      .filter((t) => /^wcag/i.test(String(t)))
      .map((t) => t.replace(/^wcag(\d+)/i, "$1"))
      .slice(0, 3),
    impact: r.impact,
    effort: "unknown",
  }));

  const fixes = vCountable.map((r) => ({
    target: r?.nodes?.[0]?.target?.[0] || "",
    description: r.help,
    codeExample: "",
  }));

  const qaChecklist = vCountable.map((r) => `Verify: ${r.help}`);

  const summary = `${engine} found ${counts.total} issues (${counts.high} high, ${counts.medium} medium, ${counts.low} low).`;

  return {
    json: {
      ...i.json,
      engine,
      violations_count: counts.total,
      countable_violations: vCountable,
      high_impact_count: counts.high,
      plan_json: {
        summary,
        prioritized,
        fixes,
        qaChecklist,
      },
    },
  };
});

// --- retired criteria --------------------------------------------------------
// W3C removed 4.1.1 Parsing in WCAG 2.2 and advises treating it as always
// satisfied for HTML and XML content. HTML CodeSniffer still emits F77 for it.
// On one live scan this inflated 31 real failures to 99.
// https://www.w3.org/WAI/standards-guidelines/wcag/faq
const OBSOLETE_SC = ["4.1.1"];

function scFromRuleId(id) {
  const s = String(id || "");
  let m = s.match(/Guideline\d_\d\.(\d)_(\d)_(\d+)/);
  if (m) return m[1] + "." + m[2] + "." + m[3];
  m = s.match(/\b(\d)\.(\d)\.(\d+)\b/);
  if (m) return m[1] + "." + m[2] + "." + m[3];
  return null;
}

function isObsoleteFinding(v) {
  if (v && v.isObsolete === true) return true;
  const sc = (v && v.wcag_sc) || scFromRuleId(v && (v.id || v.code || v.rule));
  return !!sc && OBSOLETE_SC.indexOf(sc) !== -1;
}

const parseNode = $node["Generate Violations Plan (Rule-based)"].json;

const norm = (s) => {
  const v = String(s || "").toLowerCase();
  if (["critical", "serious", "error", "high"].includes(v)) return "high";
  if (["moderate", "warning", "medium", "med"].includes(v)) return "medium";
  if (["minor", "notice", "low"].includes(v)) return "low";
  return "-";
};

const raw = Array.isArray(parseNode.scan_raw?.violations)
  ? parseNode.scan_raw.violations
  : [];
const rawNorm = raw.map((r) => ({ impact: norm(r.impact || r.type) }));
const aiCountable = rawNorm.filter((x) => !isObsoleteFinding(x));

const counts = {
  total: aiCountable.length,
  high: aiCountable.filter((x) => x.impact === "high").length,
  medium: aiCountable.filter((x) => x.impact === "medium").length,
  low: aiCountable.filter((x) => x.impact === "low").length,
  obsolete: rawNorm.length - aiCountable.length,
};

const content =
  ($json.message && $json.message.content) ||
  $json.content ||
  $json.plan_json ||
  {};

const srcSummary = typeof content.summary === "string" ? content.summary : "";
const srcPrioritized = Array.isArray(content.prioritized) ? content.prioritized : [];
const srcFixes = Array.isArray(content.fixes) ? content.fixes : [];
const srcQA = Array.isArray(content.qaChecklist) ? content.qaChecklist : [];

const prioritized = srcPrioritized.map((p) => ({
  issueId: p.issueId || p.id || "",
  wcag: Array.isArray(p.wcag) ? p.wcag : [],
  impact: norm(p.impact),
  effort: String(p.effort || "").toLowerCase(),
}));

const fixes = srcFixes.map((f) => ({
  target: f.target || f.selector || "",
  description:
    f.description || f.title || f.summary || f.issueId || f.id || f.fix || "",
  codeExample: f.codeExample || f.code || f.snippet || f.example || "",
}));

const qaChecklist = srcQA.map((x) =>
  typeof x === "string"
    ? x
    : x.item || x.description || x.help || x.title || x.id || ""
);

return [
  {
    json: {
      ...parseNode,
      ...$json,
      violations_count: counts.total,
      high_impact_count: counts.high,
      plan_json: {
        summary: srcSummary,
        prioritized,
        fixes,
        qaChecklist,
      },
    },
    binary: $binary,
  },
];

// --- retired criteria --------------------------------------------------------
// W3C removed 4.1.1 Parsing in WCAG 2.2 and advises treating it as always
// satisfied for HTML and XML content. HTML CodeSniffer still emits F77 for it.
// On one live scan this inflated 31 real failures to 99.
// https://www.w3.org/WAI/standards-guidelines/wcag/faq
const OBSOLETE_SC = ["4.1.1"];

function scFromRuleId(id) {
  const s = String(id || "");
  let m = s.match(/Guideline\d_\d\.(\d)_(\d)_(\d+)/);
  if (m) return m[1] + "." + m[2] + "." + m[3];
  m = s.match(/\b(\d)\.(\d)\.(\d+)\b/);
  if (m) return m[1] + "." + m[2] + "." + m[3];
  return null;
}

function isObsoleteFinding(v) {
  if (v && v.isObsolete === true) return true;
  const sc = (v && v.wcag_sc) || scFromRuleId(v && (v.id || v.code || v.rule));
  return !!sc && OBSOLETE_SC.indexOf(sc) !== -1;
}

function esc(s) {
  if (!s && s !== 0) return "-";
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function normImpact(x) {
  const v = String(x || "").toLowerCase();
  if (["critical", "serious", "error", "high"].includes(v)) return "high";
  if (["moderate", "warning", "medium", "med"].includes(v)) return "medium";
  if (["minor", "notice", "low"].includes(v)) return "low";
  return "-";
}

function impactColor(v) {
  if (v === "high") return "#d32f2f";
  if (v === "medium") return "#f57c00";
  if (v === "low") return "#388e3c";
  return "#555";
}

// Get the scanned URL from scan_raw, not from $json.url which contains Cloudinary URL
const scannedUrl = $json.scan_raw?.url || $json.context?.url || $json.url || "N/A";

const aiMode = String($json.ai_mode || $env.AI_MODE || "").toUpperCase();
const aiEnabled = aiMode && aiMode !== "OFF";

const meta = $json.scan_raw?.testEngine || {};
const ts = $json.scan_raw?.timestamp
  ? new Date($json.scan_raw.timestamp).toISOString()
  : new Date().toISOString();

const engineName = String(meta.name || $env.SCAN_ENGINE || "unknown").toLowerCase();

const raw = Array.isArray($json.scan_raw?.violations) ? $json.scan_raw.violations : [];

const rawNorm = raw.map((x) => ({
  id: x.id || x.rule || x.issueId || "-",
  impact: normImpact(x.impact || x.type),
  help: x.help || x.description || x.message || "-",
  nodes: Array.isArray(x.nodes) ? x.nodes : [],
  helpUrl: x.helpUrl || x.url || "",
}));

// Findings for retired criteria are reported separately and never counted as
// conformance failures.
const countable = rawNorm.filter((x) => !isObsoleteFinding(x));

const counts = {
  total: countable.length,
  high: countable.filter((x) => x.impact === "high").length,
  medium: countable.filter((x) => x.impact === "medium").length,
  low: countable.filter((x) => x.impact === "low").length,
  obsolete: rawNorm.length - countable.length,
};

const grouped = countable.reduce((acc, x) => {
  const key = x.id || "-";
  if (!acc[key]) acc[key] = [];
  acc[key].push(x);
  return acc;
}, {});

const groupedRows = Object.entries(grouped)
  .map(([rule, items]) => {
    const innerTableRows = items
      .map((x) => {
        const color = impactColor(x.impact);
        const target = x?.nodes?.[0]?.target?.[0] ? esc(x?.nodes?.[0]?.target?.[0]) : "-";
        return `
          <tr>
            <td style="color:${color};font-weight:bold;">${esc(x.impact)}</td>
            <td class="wrap-text">${esc(x.help)}</td>
            <td class="wrap-text">${target}</td>
          </tr>
        `;
      })
      .join("");

    return `
      <tr>
        <td colspan="3" class="details-container">
          <details>
            <summary>${esc(rule)} (${items.length} issue${items.length > 1 ? "s" : ""})</summary>
            <div class="details-content">
              <table class="nested-table">
                <thead>
                  <tr>
                    <th>Impact</th>
                    <th>Help</th>
                    <th>Target</th>
                  </tr>
                </thead>
                <tbody>
                  ${innerTableRows}
                </tbody>
              </table>
            </div>
          </details>
        </td>
      </tr>
    `;
  })
  .join("");

const prioritized = Array.isArray($json.plan_json?.prioritized) ? $json.plan_json.prioritized : [];

const prioritizedRows = prioritized.length
  ? prioritized
      .map((p) => {
        const wcag = Array.isArray(p.wcag) ? p.wcag.join(", ") : "";
        const color = impactColor(p.impact);
        return `
          <tr>
            <td>${esc(p.issueId || "")}</td>
            <td>${esc(wcag)}</td>
            <td style="color:${color};font-weight:bold;">${esc(p.impact || "-")}</td>
            <td>${esc(p.effort || "-")}</td>
          </tr>
        `;
      })
      .join("")
  : `<tr><td colspan="4" style="text-align:center;color:#888;">No prioritized items</td></tr>`;

const fixes = Array.isArray($json.plan_json?.fixes) ? $json.plan_json.fixes : [];

const fixesRows = fixes.length
  ? fixes
      .map((f) => {
        const tgt = f.target ? `<div><b>Target:</b> ${esc(f.target)}</div>` : "";
        const desc = f.description ? `<div>${esc(f.description)}</div>` : "";
        const code = f.codeExample ? `<pre>${esc(f.codeExample)}</pre>` : "<pre>-</pre>";
        return `
          <tr>
            <td>${tgt}${desc}</td>
            <td>${code}</td>
          </tr>
        `;
      })
      .join("")
  : `<tr><td colspan="2" style="text-align:center;color:#888;">No AI fixes available</td></tr>`;

const qa = Array.isArray($json.plan_json?.qaChecklist) ? $json.plan_json.qaChecklist : [];

const qaRows = qa.length
  ? qa
      .map(
        (x) => `
        <tr>
          <td>${esc(
            typeof x === "string"
              ? x
              : x.item || x.description || x.help || x.title || x.id || "-"
          )}</td>
        </tr>
      `
      )
      .join("")
  : `<tr><td style="text-align:center;color:#888;">No QA checklist available</td></tr>`;

const sumText =
  typeof $json.plan_json?.summary === "string" && $json.plan_json.summary
    ? `<p>${esc($json.plan_json.summary)}</p>`
    : "";

const summaryCounts = `
  <table>
    <tr>
      <th>Total issues</th>
      <th>High</th>
      <th>Medium</th>
      <th>Low</th>
    </tr>
    <tr>
      <td>${counts.total}</td>
      <td>${counts.high}</td>
      <td>${counts.medium}</td>
      <td>${counts.low}</td>
    </tr>
  </table>
`;

const modeLabel = aiEnabled ? `AI (${esc(aiMode)})` : "Rule-based (OFF)";

const html =
  "<!doctype html>" +
  '<meta charset="utf-8">' +
  "<title>Accessibility Report - " +
  esc(scannedUrl) +
  "</title>" +
  `<style>
    body {
      font-family: Arial, sans-serif;
      color: #333;
      margin: 20px;
      line-height: 1.5;
    }
    h1, h2 {
      color: #2c3e50;
    }
    h2 { margin-top: 30px; }
    table {
      border-collapse: collapse;
      width: 100%;
      margin-top: 15px;
      table-layout: fixed;
      word-wrap: break-word;
    }
    th, td {
      border: 1px solid #ccc;
      padding: 8px 10px;
      text-align: left;
      vertical-align: top;
    }
    th {
      background: #f4f4f4;
    }
    .wrap-text {
      white-space: normal;
      word-break: break-word;
    }
    pre {
      margin: 0;
      white-space: pre-wrap;
      word-wrap: break-word;
      font-family: monospace;
      background: #f9f9f9;
      padding: 6px;
      border-radius: 4px;
      overflow-x: auto;
    }
    .info-box {
      background: #f7faff;
      border: 1px solid #cce5ff;
      padding: 12px;
      border-radius: 8px;
      margin-bottom: 20px;
    }
    .ai-section {
      background: #fffdf5;
      border: 1px solid #ffe58f;
      padding: 15px;
      border-radius: 8px;
      margin-top: 25px;
    }
    .ai-section h2 { color: #ad6800; }
    summary {
      font-weight: bold;
      background: #f4f4f4;
      padding: 10px;
      cursor: pointer;
      outline: none;
      border-radius: 4px;
    }
    summary:hover {
      background: #e9f3ff;
    }
    details {
      border: 1px solid #ccc;
      border-radius: 4px;
      overflow: hidden;
    }
    details[open] summary {
      border-bottom: 1px solid #ccc;
    }
    .details-container {
      padding: 4px 0;
      border: none;
    }
    .details-content {
      padding: 10px;
    }
    .nested-table {
      margin-top: 0;
    }
    .nested-table th {
      background: #f9f9f9;
    }
    .nested-table tr:nth-child(even) {
      background: #fff;
    }

    @media print {
      body { margin: 0; font-size: 11pt; }
      details > *:not(summary) { display: block !important; }
      details { border: 1px solid #ccc; page-break-inside: avoid; }
      summary { cursor: default; background: #f4f4f4; }
      h2, h3 { page-break-after: avoid; }
      tr, pre { page-break-inside: avoid; }
      td, pre { word-break: break-word; }
      .info-box, .ai-section { page-break-inside: avoid; }
      a[href]:after { content: " (" attr(href) ")"; font-size: 9pt; color: #555; }
    }
</style>` +
  "<h1>Accessibility Report</h1>" +
  '<div class="info-box">' +
  "<p><b>URL:</b> " + esc(scannedUrl) + "</p>" +
  "<p><b>Run ID:</b> " + esc($json.context?.run_id || "-") + "</p>" +
  "<p><b>Engine:</b> " + esc(meta.name || engineName) + " " + esc(meta.version || "") + "</p>" +
  "<p><b>Mode:</b> " + modeLabel + "</p>" +
  "<p><b>Timestamp:</b> " + esc(ts) + "</p>" +
  "<p><b>Total Violations:</b> " + counts.total + " (" + counts.high + " high, " + counts.medium + " medium, " + counts.low + " low)</p>" +
  (aiEnabled ? "<p><b>AI Prioritized:</b> " + prioritized.length + "</p>" : "") +
  "</div>" +
  (counts.total === 0
    ? '<div class="info-box" style="border-color:#c3e6cb;background:#f0fff4;">' +
      '<p style="margin:0 0 8px;font-weight:bold;color:#1e7e34;">No violations found</p>' +
      '<p style="margin:0;">This page passed all automated checks performed by ' +
      esc(meta.name || engineName) + ' at the configured conformance level.</p>' +
      '<p style="margin:8px 0 0;color:#555;font-size:13px;">Automated testing detects a portion of ' +
      'accessibility issues. Manual review is recommended to confirm full conformance.</p>' +
      '</div>'
    : "<h2>Violations (grouped by rule)</h2>" +
      "<table>" +
      groupedRows +
      "</table>") +
  (aiEnabled
    ? '<div class="ai-section">' +
      "<h2>AI Analysis</h2>" +
      "<h3>Summary</h3>" +
      sumText +
      summaryCounts +
      "<h3>Prioritized Overview</h3>" +
      "<table><tr><th>issue_id</th><th>wcag</th><th>impact</th><th>effort</th></tr>" +
      prioritizedRows +
      "</table>" +
      "<h3>Suggested Fixes</h3>" +
      "<table><tr><th>Description/Target</th><th>Code Example</th></tr>" +
      fixesRows +
