// Concrete, per element actions. The scanner already reports the exact element
// and often the exact change to make. Grouping identical instructions means a
// reader sees each distinct action once, with every element it applies to.
function actionTable(actions) {
  if (!Array.isArray(actions) || actions.length === 0) return '';

  const byFix = new Map();
  actions.forEach(a => {
    const key = a.fix || 'See the criterion reference for this issue';
    if (!byFix.has(key)) byFix.set(key, []);
    byFix.get(key).push(a.target);
  });

  const rows = Array.from(byFix.entries()).map(([fix, targets]) => {
    const shown = targets.slice(0, 12);
    const extra = targets.length - shown.length;
    const list = shown.map(t => '<code>' + esc(t) + '</code>').join('<br>') +
      (extra > 0 ? '<br><span style="color:#666;">and ' + extra + ' more</span>' : '');
    return '<tr><td style="width:50%;">' + esc(fix) + '</td>' +
           '<td style="font-size:12px;">' + list + '</td>' +
           '<td style="text-align:right;width:12%;">' + targets.length + '</td></tr>';
  }).join('');

  return '<p><b>Apply these changes:</b></p>' +
    '<table class="nested-table"><thead><tr>' +
    '<th>What to change</th><th>Elements</th><th style="text-align:right;">Count</th>' +
    '</tr></thead><tbody>' + rows + '</tbody></table>';
}

  // Group by success criterion. Guidance for a criterion is identical for every
  // finding that breaks it, so one block per criterion is shown with a count
  // rather than one block per finding. Findings scale, guidance does not.
  const byCriterion = new Map();
  remediationEntries.forEach(v => {
    const key = String(v.wcag_sc || '-');
    if (!byCriterion.has(key)) {
      byCriterion.set(key, { rd: v.remediationDetails, count: 0, high: 0, actions: [] });
    }
    const entry = byCriterion.get(key);
    entry.count += 1;
    if (normImpact(v.impact || v.type) === 'high') entry.high += 1;
    if (v.elementTarget || v.specificFix) {
      entry.actions.push({
        target: v.elementTarget || '-',
        // Prefer the concrete value the scanner reported. Where there is none,
        // use its description of the problem, which still differs per issue and
        // must not be collapsed with unrelated findings under the same criterion.
        fix: v.specificFix || String(v.help || v.description || v.message || '').trim() || null,
        impact: normImpact(v.impact || v.type)
      });
    }
  });

  // Most severe first, then most frequent.
  const ordered = Array.from(byCriterion.entries()).sort((a, b) => {
    if (b[1].high !== a[1].high) return b[1].high - a[1].high;
    return b[1].count - a[1].count;
  });

  const summaryRows = ordered.map(([sc, e]) =>
    '<tr><td>WCAG ' + esc(sc) + ', ' + esc(e.rd.title || '-') + '</td>' +
    '<td style="text-align:right;">' + e.count + '</td>' +
    '<td style="text-align:right;">' + e.high + '</td></tr>'
  ).join('');

  const remSummary =
    '<table><thead><tr>' +
    '<th>Criterion</th><th style="text-align:right;">Findings</th><th style="text-align:right;">High</th>' +
    '</tr></thead><tbody>' + summaryRows + '</tbody></table>';

  const remRows = ordered.map(([sc, e]) => {
    const rd = e.rd;
    const howToFix = Array.isArray(rd.howToFix) ? rd.howToFix.map(h => '<li>' + esc(h) + '</li>').join('') : '';
    const label = e.count === 1 ? '1 finding' : e.count + ' findings';
    const obsoleteTag = rd.obsolete
      ? ' <span style="font-weight:normal;color:#1e7e34;">(criterion obsolete, not a conformance failure)</span>'
      : '';
    return '<tr><td colspan="2" class="details-container">' +
      '<details><summary>WCAG ' + esc(sc) + ', ' + esc(rd.title || '-') +
      ' <span style="font-weight:normal;color:#666;">(' + label + ')</span>' + obsoleteTag + '</summary>' +
      '<div class="details-content">' +
      // Plain language first, so a non specialist reader starts with the point.
      // An authored line takes precedence; otherwise the W3C guideline text is
      // used, which is already written plainly and needs no authoring.
      (rd.plainLanguage
        ? '<p>' + esc(rd.plainLanguage) + '</p>'
        : (rd.guidelineIntent ? '<p>' + esc(rd.guidelineIntent) + '</p>' : '')) +
      (rd.requirement
        ? '<p><b>What WCAG requires:</b> ' + esc(rd.requirement) + '</p>' +
          (Array.isArray(rd.exceptions) && rd.exceptions.length
            ? '<p><b>Exceptions:</b></p><ul>' +
              rd.exceptions.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>'
            : '')
        : '<p><b>Why it matters:</b> ' + esc(rd.whyItMatters || '') + '</p>') +
      (Array.isArray(rd.sufficientTechniques) && rd.sufficientTechniques.length
        ? '<p><b>Sufficient techniques published by W3C:</b></p><ul>' +
          rd.sufficientTechniques.slice(0, 10).map(t =>
            '<li><a href="' + esc(t.url) + '">' + esc(t.id) + '</a> ' + esc(t.title) + '</li>'
          ).join('') +
          (rd.sufficientTechniques.length > 10
            ? '<li style="color:#666;">and ' + (rd.sufficientTechniques.length - 10) + ' more</li>'
            : '') +
          '</ul>'
        : '') +
      (Array.isArray(rd.commonFailures) && rd.commonFailures.length
        ? '<p><b>Documented failures for this criterion:</b></p><ul>' +
          rd.commonFailures.slice(0, 8).map(t =>
            '<li><a href="' + esc(t.url) + '">' + esc(t.id) + '</a> ' + esc(t.title) + '</li>'
          ).join('') + '</ul>'
        : '') +
      (howToFix ? '<p><b>How to fix:</b></p><ul>' + howToFix + '</ul>' : '') +
      (rd.understandingUrl
        ? '<p><a href="' + esc(rd.understandingUrl) + '">Understanding this criterion (W3C)</a></p>'
        : '') +
      (rd.fromScanner
        ? '<p style="color:#666;font-size:13px;">Detailed guidance for this criterion is not yet in the remediation library. ' +
          'The description above is reported by the scan engine. See ' +
          '<a href="https://www.w3.org/WAI/WCAG22/Understanding/">Understanding WCAG</a> for the full criterion.</p>'
        : '') +
      (rd.codeExample ? '<p><b>Code example:</b></p><pre>' + esc(rd.codeExample) + '</pre>' : '') +
      actionTable(e.actions) +
      '</div></details></td></tr>';
  }).join('');

  remediationHtml = '<div class="ai-section" style="border-color:#c3e6cb;background:#f0fff4;">' +
    '<h2 style="color:#1e7e34;">Remediation Guidance</h2>' +
    '<p style="font-size:13px;color:#555;margin-top:0;">Requirement text, techniques and ' +
    'documented failures are from the Web Content Accessibility Guidelines and Techniques ' +
    'for WCAG, Copyright World Wide Web Consortium, reproduced without alteration under the ' +
    '<a href="https://www.w3.org/copyright/document-license/">W3C Document License</a>.</p>' +
    remSummary +
    '<table>' + remRows + '</table>' +
    '</div>';
}


