// Resolve law group names to actual law arrays
function resolveLaws(lawGroupNames, lawGroups) {
  const resolved = new Set();
  for (const groupName of lawGroupNames) {
    const laws = lawGroups[groupName];
    if (laws) {
      laws.forEach(l => resolved.add(l));
    } else {
      resolved.add(groupName);
    }
  }
  return Array.from(resolved);
}

// Build a flat SC -> { description, resolvedLaws[] } lookup from wcag21 + wcag22
function buildScLookup(mapping) {
  const lookup = {};
  const lawGroups = mapping.lawGroups || {};
  for (const section of ['wcag21', 'wcag22']) {
    const scs = mapping[section] || {};
    for (const [sc, info] of Object.entries(scs)) {
      lookup[sc] = {
        description: info.description,
        resolvedLaws: resolveLaws(info.laws || [], lawGroups)
      };
    }
  }
  return lookup;
}

const scLookup = buildScLookup(wcagGlobalMapping);

// Determine compliance profile from context or env
const profileKey = (
  $json.context?.complianceProfile ||
  $json.complianceProfile ||
  ($env.COMPLIANCE_PROFILE || '')
).toLowerCase().trim();

const profile = complianceProfiles[profileKey] || null;

// Extract WCAG SC from violation tags or id
function extractSC(violation) {
  // Try tags first (axe format: tags like "wcag2a", "wcag143" -> "1.4.3")
  if (Array.isArray(violation.tags)) {
    for (const tag of violation.tags) {
      const m = String(tag).match(/^wcag(\d)(\d)(\d+)$/i);
      if (m) return m[1] + '.' + m[2] + '.' + m[3];
    }
  }
  // Try wcag field directly
  if (violation.wcag) return String(violation.wcag);
  // Try id field (pa11y format: "WCAG2AA.Principle1.Guideline1_4.1_4_3...")
  const idStr = String(violation.id || '');
  const idMatch = idStr.match(/(\d+)_(\d+)_(\d+)/);
  if (idMatch) return idMatch[1] + '.' + idMatch[2] + '.' + idMatch[3];
  return null;
}

// Enrich scan_raw violations with jurisdictional impact
const violations = Array.isArray($json.scan_raw?.violations) ? $json.scan_raw.violations : [];


// Law names must appear once. The mapping carries two spellings of the Japanese
// standard, "JIS X 8341-3" and "JIS X 8341-3 (Japan)", which would otherwise
// both surface under All Jurisdictions.
function canonicalLaw(name) {
  const s = String(name || "").trim();
  if (/^JIS X 8341-3/i.test(s)) return "JIS X 8341-3 (Japan)";
  return s;
}

function dedupeLaws(list) {
  const out = [];
  const seen = new Set();
  for (const raw of list || []) {
    const name = canonicalLaw(raw);
    const key = name.toLowerCase();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(name);
  }
  return out;
}

const enrichedViolations = violations.map(v => {
  const sc = extractSC(v);
  const scInfo = sc ? scLookup[sc] : null;

  let jurisdictionalImpact = [];
  if (scInfo) {
    if (profile) {
      jurisdictionalImpact = scInfo.resolvedLaws.filter(resolvedLaw => {
      const rLower = resolvedLaw.toLowerCase();
      return profile.laws.some(profileLaw => {
        const pLower = profileLaw.toLowerCase();
        return rLower === pLower || rLower.includes(pLower) || pLower.includes(rLower);
      });
    });
    // If the SC maps to core_global, it's universally applicable.
    // Include ALL of the profile's laws since they all reference WCAG.
    const scEntry = (wcagGlobalMapping.wcag21 && wcagGlobalMapping.wcag21[sc]) ||
                     (wcagGlobalMapping.wcag22 && wcagGlobalMapping.wcag22[sc]);
    if (scEntry && scEntry.laws && scEntry.laws.includes('core_global')) {
      for (const pLaw of profile.laws) {
        if (!jurisdictionalImpact.some(j => j.toLowerCase() === pLaw.toLowerCase())) {
          jurisdictionalImpact.push(pLaw);
        }
      }
    }
    // Also check non-core law groups the SC maps to
    if (scEntry && scEntry.laws) {
      const lawGroups = wcagGlobalMapping.lawGroups || {};
      for (const groupName of scEntry.laws) {
        if (groupName === 'core_global') continue;
        const groupLaws = lawGroups[groupName] || [];
        for (const gLaw of groupLaws) {
          const gLower = gLaw.toLowerCase();
          for (const pLaw of profile.laws) {
            const pLower = pLaw.toLowerCase();
            if (gLower === pLower || gLower.includes(pLower) || pLower.includes(gLower)) {
              if (!jurisdictionalImpact.includes(gLaw)) {
                jurisdictionalImpact.push(gLaw);
              }
            }
          }
        }
      }
    }
    } else {
      // No profile selected means "All Jurisdictions". Previously this used
      // only the criterion's own law groups, so laws that live solely in a
      // regional group (ADA, EAA, Equality Act 2010, CVAA) never appeared.
      // A criterion mapped to core_global applies everywhere, so surface every
      // law the product covers.
      jurisdictionalImpact = scInfo.resolvedLaws.slice();
      const scEntryAll = (wcagGlobalMapping.wcag21 && wcagGlobalMapping.wcag21[sc]) ||
                         (wcagGlobalMapping.wcag22 && wcagGlobalMapping.wcag22[sc]);
      if (scEntryAll && Array.isArray(scEntryAll.laws) && scEntryAll.laws.includes('core_global')) {
        for (const p of Object.values(complianceProfiles)) {
          for (const pLaw of p.laws) {
            if (!jurisdictionalImpact.some(j => j.toLowerCase() === pLaw.toLowerCase())) {
              jurisdictionalImpact.push(pLaw);
            }
          }
        }
      }
    }
  }

  // Attach remediation from library
  let remediationDetails = null;
  if (sc && remediationLibrary[sc]) {
    remediationDetails = remediationLibrary[sc];
  }

  // W3C removed 4.1.1 Parsing in WCAG 2.2 and advises it be treated as always
  // satisfied for HTML and XML. Flag it so a report does not present an
  // obsolete criterion as a live failure.
  const isObsolete = !!(remediationDetails && remediationDetails.obsolete);

  // Scanners often embed a concrete instruction in the help text, for example
  // "Recommendation: change text color to #e8741f". Pull it out so the report
  // can show the specific action next to the element it applies to.
  const helpText = String(v.help || v.description || v.message || '');
  const recMatch = helpText.match(/Recommendation:\s*(.+?)(?:\s*$|\.$)/i);
  const specificFix = recMatch ? recMatch[1].trim().replace(/\.$/, '') : null;

  const target =
    (Array.isArray(v.nodes) && v.nodes[0] && Array.isArray(v.nodes[0].target) && v.nodes[0].target[0]) ||
    v.selector || v.target || null;

  return {
    ...v,
    wcag_sc: sc,
    jurisdictionalImpact: dedupeLaws(jurisdictionalImpact),
    remediationDetails,
    isObsolete,
    specificFix,
    elementTarget: target
  };
});

// Build byJurisdiction grouping.
