  for (const law of (v.jurisdictionalImpact || [])) {
    if (!byJurisdiction[law]) byJurisdiction[law] = [];
    byJurisdiction[law].push({
      id: v.id || '-',
      wcag: v.wcag_sc || '-',
      help: v.help || v.description || v.message || '-',
      impact: v.impact || v.type || '-'
    });
  }
}

// Compute compliance summary
const complianceSummary = {
  profile: profileKey || 'all',
  profileName: profile ? profile.name : 'All Jurisdictions',
  totalFindings: countableViolations.length,
  findingsWithJurisdictionalImpact: countableViolations.filter(v => v.jurisdictionalImpact.length > 0).length,
  jurisdictionsAffected: Object.keys(byJurisdiction).length,
  byJurisdiction: Object.fromEntries(
    Object.entries(byJurisdiction).map(([law, issues]) => [law, issues.length])
